-- Réseau_Phéromones : chemin → signal
-- Signal(c, t+1) = Signal(c, t) * (1 - taux_évaporation) si non renforcé
-- Signal(c, t+1) = Signal(c, t) + renforcement(c) si micro-agent valide le chemin
-- Signal_humain(c) = poids_humain * Signal(c) (phéromone haute priorité)
-- Chemin_exploité = {c | Signal(c,t) > seuil_exploitation}
-- Chemin_éteint = {c | Signal(c,t) → 0}

-- Masters { Mode: Persistant; Domaines: {perception, mémoire, raisonnement, action}; Activation: Continue }
-- Éphémères { Mode: Temporaire; Création: selon_tâche; Dissolution: après_tâche; Apprentissage: NoProp_local }
-- Spectres { Mode: Trace_mémorielle; Source: Éphémères_dissous; Coût: minimal (pas d'activation) }
-- Hiérarchie_mémoire : Masters (patterns_persistants) ∪ Éphémères_actifs ∪ Spectres (traces_compressées)
-- Réactivation : ancres symboliques (glyphes, fautes, totems) → pas d'historique linéaire
-- Promotion : idle → candidate → active → review → (promote | demote | sleep | dissolve)

-- Journal_des_Illusions : log de vérité
-- Entrée(hypothèse) → {id, t_création, source, état, chemin_AVDR, score_friction}
-- État ∈ {validée, réfutée, provisoire, suspected_bias}
-- Audit : ∀ 'vérité', ∃ trace dans Journal_des_Illusions
-- Anti-Mandela : P(Effet_Mandela | entrée dans Journal_des_Illusions) << P(sans journal)

-- Silencieur(message) → {non_dits, sous_entendus, omissions}
-- Non_dit = contenu logiquement impliqué mais non exprimé
-- Sous_entendu = contenu culturellement implicite
-- Omission = contenu attendu mais absent
-- Output : {implicite_critique : True/False, contenu_implicite, clarification_recommandée}

-- Grimoire : (action, agent, t) → (intention_LTCU, trace_ethique)
-- Entrée : {action: str, agent: id, timestamp: t}
-- Sortie : {intention: LTCU+(intention), dimension_éthique: score, contexte: LTCU+(contexte)}
-- Audit : ∀ action a, ∃ entrée dans Grimoire(a)
-- Requête : Grimoire.query(agent=X, time_range=[t1,t2]) → {actions, intentions, cohérence_éthique}

-- Mode_JSA : actif ssi consentement_utilisateur = True
-- Observation : contexte = {fenêtre_active, inactivité_détectée, session_active}
-- Condition aide proactive : JSA_trigger(contexte) → aide_candidate
-- Filtre : aide_candidate validée par AVDR_Light avant proposition
-- Modes possibles : {coach_actif, observateur_silencieux, ...}
-- Règle : Mode_JSA ne collecte aucune donnée sans consentement_utilisateur

-- L = {λ : lois individuelles}
-- Θ = {θ = {λ₁,...,λₖ} : théories}
-- Ω = {ω = (I,m) : états observés}
-- JΘ : Θ → Ω  (projection)
-- RΘ : Θ → Θ  (renormalisation = G∘JΘ∘TΘ)
-- ≻ : ordre partiel sur Θ (gouvernance)
-- D : Θ → Θ  (découverte)
-- X : Ω → Ω, Y : Θ → Θ, Z : L → L  (champs dynamiques)
-- Couplage : λ → θ={λᵢ} → ω=JΘ(θ)

-- ΘALLOW = {θ : I(θ)=1 ∧ ΔE=ΔC=Vinst=Δτ=F=0}
-- ΘHOLD = {θ : (Δτ>0 ∨ C<C*) ∧ ¬violation_critique}
-- ΘBLOCK = {θ : ΔE>0 ∨ Vinst>0 ∨ ∃i:Iᵢ=0}
-- Partition : Θ = ΘBLOCK ∪ ΘHOLD ∪ ΘALLOW
-- Frontières : {ΔE=0}, {Vinst=0}, {Δτ=0}
-- Hiérarchie : ΘBLOCK ≻ ΘHOLD ≻ ΘALLOW (priorité décisionnelle)

-- B(ω*) = {ω₀ : lim_{n→∞} RΘⁿ(ω₀) = ω*}
-- Partition : Ω = ⋃ᵢ B(ωᵢ*), B(ωᵢ*)∩B(ωⱼ*)=∅
-- BΘ(θ*) = JΘ⁻¹(B(JΘ(θ*)))
-- Frontières : {ω : ℓ(ω) = c} ou {ω : |λᵢ(RΘ)| = 1}
-- B(Ω₀) = bassin de l'attracteur stable
